package com.arena.core.facility;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.http.HttpStatus;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
import static com.arena.core.facility.FacilityContracts.*;
@io.swagger.v3.oas.annotations.tags.Tag(name="Facilities")
@RestController @RequestMapping("/api/v1/academies") @RequiredArgsConstructor
public class FacilityController {
 private final FacilityService service;
 @io.swagger.v3.oas.annotations.Operation(summary="Get facility configuration context", description="Owner or Manager with active current-tenant membership. academyId must equal the authenticated academy; sport and facility must belong to it. No Running Sessions API is implemented. Resolve the academy from the authenticated actor; return registered sports and authoritative maxPerType/maxBulk limits.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @io.swagger.v3.oas.annotations.responses.ApiResponse(responseCode="200",description="Successful operation",content=@io.swagger.v3.oas.annotations.media.Content(mediaType="application/json",schema=@io.swagger.v3.oas.annotations.media.Schema(implementation=com.arena.core.documentation.ResponseDocumentation.FacilityContext.class)))
 @GetMapping("/current/facilities/context") public Map<String,Object> context(@AuthenticationPrincipal Jwt jwt){return service.context(jwt);}
 @io.swagger.v3.oas.annotations.Operation(summary="Generate facilities", description="Owner or Manager with active current-tenant membership. academyId must equal the authenticated academy; sport and facility must belong to it. No Running Sessions API is implemented. Generate independently configured facilities atomically. Idempotency-Key is a required UUID scoped to the academy. Validated replay of the same key/sport/counts returns the stored result with HTTP 201, even if capability was subsequently disabled. A different payload with the same key returns 409. Types: SNOOKER \u2192 ENGLISH, FRENCH, POOL, SEMI_ENGLISH; BADMINTON \u2192 COURT. Duplicate types and unknown fields are rejected. Each count is 1..maxPerType (default 50); combined count <=maxBulk (default 200), fetched from context. Generated IDs/codes are immutable; prices start null/unconfigured. Limits are deployment-configurable. Creation does not accept prices or names.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.FACILITY_CAPABILITY_DISABLED,com.arena.core.exception.ErrorCode.FACILITY_CONCURRENCY_FAILURE,com.arena.core.exception.ErrorCode.FACILITY_IDEMPOTENCY_CONFLICT,com.arena.core.exception.ErrorCode.FACILITY_INVALID_REQUEST,com.arena.core.exception.ErrorCode.FACILITY_NOT_FOUND,com.arena.core.exception.ErrorCode.FACILITY_UNSUPPORTED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @io.swagger.v3.oas.annotations.parameters.RequestBody(required=true,content=@io.swagger.v3.oas.annotations.media.Content(mediaType="application/json",schema=@io.swagger.v3.oas.annotations.media.Schema(implementation=com.arena.core.documentation.FacilityDocumentation.Generate.class)))
 @PostMapping("/{academyId}/sports/{sportId}/facilities/bulk") @ResponseStatus(HttpStatus.CREATED)
 public Result create(@AuthenticationPrincipal Jwt jwt,@PathVariable Long academyId,@PathVariable Long sportId,@RequestHeader("Idempotency-Key") UUID key,@RequestBody byte[] body){return service.create(jwt,academyId,sportId,key,service.parse(body));}
 @io.swagger.v3.oas.annotations.Operation(summary="List registered sport facilities", description="Owner or Manager with active current-tenant membership. academyId must equal the authenticated academy; sport and facility must belong to it. No Running Sessions API is implemented. Read saved supported-sport facilities, including inactive or unconfigured rows. A disabled Play & Facility Access capability does not hide history. Legacy type-null rows are returned without conversion.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.FACILITY_NOT_FOUND,com.arena.core.exception.ErrorCode.FACILITY_UNSUPPORTED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @GetMapping("/{academyId}/sports/{sportId}/facilities") public Result list(@AuthenticationPrincipal Jwt jwt,@PathVariable Long academyId,@PathVariable Long sportId){return service.list(jwt,academyId,sportId);}
 @io.swagger.v3.oas.annotations.Operation(summary="Update facility configuration in bulk", description="Owner or Manager with active current-tenant membership. academyId must equal the authenticated academy; sport and facility must belong to it. No Running Sessions API is implemented. Atomic all-or-nothing update of 1..maxBulk distinct records. Each requires facilityId>0 and version>=0 plus at least one changed field. Omitted editable fields are unchanged; explicit null clears displayName/hourlyRate/frameRate; active must be boolean, never null. Rates must be numeric >0, <=9999999999.99, at most two decimals; courts cannot have non-null frameRate. Names are stripped, max 160; blank becomes null. Unknown fields/types are rejected. All versions are checked before mutation; 409 conflicts list current and submitted versions. Preserve drafts, review latest values, then retry explicitly. Inactive/disabled sport permits deactivation-only updates, no price/name edits. Legacy type-null facilities require mapping review before modification. No session commitment writer is present, so session lock/snapshot enforcement is not claimed.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.FACILITY_CAPABILITY_DISABLED,com.arena.core.exception.ErrorCode.FACILITY_CONCURRENCY_FAILURE,com.arena.core.exception.ErrorCode.FACILITY_INVALID_REQUEST,com.arena.core.exception.ErrorCode.FACILITY_NOT_FOUND,com.arena.core.exception.ErrorCode.FACILITY_UNSUPPORTED,com.arena.core.exception.ErrorCode.FACILITY_VERSION_CONFLICT,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @io.swagger.v3.oas.annotations.parameters.RequestBody(required=true,content=@io.swagger.v3.oas.annotations.media.Content(mediaType="application/json",schema=@io.swagger.v3.oas.annotations.media.Schema(implementation=com.arena.core.documentation.FacilityDocumentation.Patch.class)))
 @PatchMapping("/{academyId}/facilities/bulk") public Result patch(@AuthenticationPrincipal Jwt jwt,@PathVariable Long academyId,@RequestBody byte[] body){return service.patch(jwt,academyId,service.parse(body));}
 @io.swagger.v3.oas.annotations.Operation(summary="Read facility audit history", description="Owner or Manager with active current-tenant membership. academyId must equal the authenticated academy; sport and facility must belong to it. No Running Sessions API is implemented. Read up to 200 append-only facility audit entries, newest first. Metadata identifies this tenant-scoped facility; audit values describe previous/current configuration.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED,com.arena.core.exception.ErrorCode.RESOURCE_NOT_FOUND,com.arena.core.exception.ErrorCode.SERVICE_UNAVAILABLE,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_EXPIRED,com.arena.core.exception.ErrorCode.USER_DISABLED})
 @GetMapping("/{academyId}/facilities/{id}/audit") public java.util.List<com.arena.core.entity.AuditEventEntity> history(@AuthenticationPrincipal Jwt jwt,@PathVariable Long academyId,@PathVariable Long id){return service.history(jwt,academyId,id);}
}
